import { useEffect, useState, type ReactNode, type FormEvent } from "react";
import { getApiBase } from "../../api/apiBase";
import { getAccessToken } from "../../api/tenant";
import { loginPassword } from "../../api/passwordLogin";

/** Read the server's login policy before mounting business catalog consumers. */
export function LocalLoginGate({ children }: { children: ReactNode }) {
  const [policy, setPolicy] = useState<"loading" | "legacy" | "password" | "error">("loading");
  const [retry, setRetry] = useState(0);
  const [authenticated, setAuthenticated] = useState(Boolean(getAccessToken()));
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => {
    const controller = new AbortController();
    setPolicy("loading");
    fetch(`${getApiBase()}/v1/auth/oidc`, { cache: "no-store", signal: controller.signal })
      .then(async (response) => {
        if (!response.ok) throw new Error();
        const config = await response.json();
        if (config.allowDevToken === true) setPolicy("legacy");
        else if (config.allowDevToken === false && config.tokenUrlConfigured === true && config.grantTypes?.includes("password")) setPolicy("password");
        else throw new Error();
      }).catch(() => { if (!controller.signal.aborted) setPolicy("error"); });
    return () => controller.abort();
  }, [retry]);
  useEffect(() => {
    const update = () => setAuthenticated(Boolean(getAccessToken()));
    window.addEventListener("aos-auth-updated", update);
    return () => window.removeEventListener("aos-auth-updated", update);
  }, []);
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (busy) return;
    const submitted = password;
    setPassword(""); setBusy(true); setError("");
    try { await loginPassword(username, submitted); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "登录失败，请重试。"); }
    finally { setBusy(false); }
  }
  if (policy === "legacy" || (policy === "password" && authenticated)) return <>{children}</>;
  return <main style={{ maxWidth: 420, margin: "12vh auto", padding: 24 }}>
    <h1>AOS 登录</h1>
    {policy === "loading" ? <p role="status">正在读取登录配置…</p> : policy === "error" ? <>
      <p role="alert">登录服务暂不可用，请重新读取配置。</p>
      <button onClick={() => setRetry((value) => value + 1)}>重试</button>
    </> : <form onSubmit={submit}>
      <p>登录后进入你有权限访问的组织与工作区。</p>
      <label>登录名<input autoComplete="username" value={username} onChange={(event) => setUsername(event.target.value)} required disabled={busy} /></label>
      <label>密码<input type="password" autoComplete="current-password" value={password} onChange={(event) => setPassword(event.target.value)} required disabled={busy} /></label>
      {error && <p role="alert">{error}</p>}
      <button type="submit" disabled={busy}>{busy ? "登录中…" : "登录"}</button>
    </form>}
  </main>;
}

import { getApiBase } from "./apiBase";
import { applyMeToTenant, clearAccessToken, getTenant, setAccessToken, type MeResponse } from "./tenant";

/** Original server authentication; credentials and refresh tokens never persist. */
export async function loginPassword(username: string, password: string): Promise<void> {
  clearAccessToken();
  try {
    const response = await fetch(`${getApiBase()}/v1/auth/token`, {
      method: "POST", cache: "no-store",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ grantType: "password", username, password }),
    });
    if (!response.ok) throw new Error();
    const tokens = await response.json();
    if (typeof tokens.access_token !== "string" || !tokens.access_token.trim()) throw new Error();
    const tenant = getTenant();
    const meResponse = await fetch(`${getApiBase()}/v1/me`, {
      cache: "no-store",
      headers: { Authorization: `Bearer ${tokens.access_token}`, "X-Org-Id": tenant.orgId, "X-Project-Id": tenant.projectId },
    });
    if (!meResponse.ok) throw new Error();
    const me: MeResponse = await meResponse.json();
    if (!me.subject || !me.orgId || !me.projectId) throw new Error();
    applyMeToTenant(me);
    setAccessToken(tokens.access_token);
  } catch {
    clearAccessToken();
    throw new Error("登录失败，请核对账号、密码及工作区访问权限后重试。");
  }
}

import { afterEach, describe, expect, it, vi } from "vitest";
import { loginPassword } from "./passwordLogin";
import { clearAccessToken, getAccessToken, getTenant } from "./tenant";
import { act, createElement } from "react";
import { createRoot } from "react-dom/client";
import { LocalLoginGate } from "../components/auth/LocalLoginGate";

afterEach(() => { vi.unstubAllGlobals(); clearAccessToken(); });
describe("human password login", () => {
  it("uses original grant and canonical me before publishing memory session", async () => {
    const fetch = vi.fn().mockResolvedValueOnce(new Response(JSON.stringify({ access_token: "signed", refresh_token: "discard" })))
      .mockResolvedValueOnce(new Response(JSON.stringify({ subject: "human", orgId: "org-org", projectId: "dev-project", workspaceName: "真实工作区", roles: ["admin"], markings: [], tokenKind: "oidc" })));
    vi.stubGlobal("fetch", fetch);
    await loginPassword("user", "private");
    expect(fetch.mock.calls[0][0]).toContain("/v1/auth/token");
    expect(JSON.parse(fetch.mock.calls[0][1].body)).toEqual({ grantType: "password", username: "user", password: "private" });
    expect(fetch.mock.calls[1][1].headers.Authorization).toBe("Bearer signed");
    expect(getAccessToken()).toBe("signed");
    expect(getTenant().subject).toBe("human");
    expect(localStorage.getItem("access_token")).toBeNull();
    expect(sessionStorage.getItem("refresh_token")).toBeNull();
  });
  it("does not retry rejected credentials or publish a session", async () => {
    const fetch = vi.fn().mockResolvedValue(new Response("private provider detail", { status: 401 }));
    vi.stubGlobal("fetch", fetch);
    await expect(loginPassword("user", "private")).rejects.toThrow("登录失败");
    expect(fetch).toHaveBeenCalledTimes(1);
    expect(getAccessToken()).toBeNull();
  });
  it("rejects incomplete token responses before fetching identity", async () => {
    const fetch = vi.fn().mockResolvedValue(new Response("{}")); vi.stubGlobal("fetch", fetch);
    await expect(loginPassword("user", "private")).rejects.toThrow("登录失败");
    expect(fetch).toHaveBeenCalledTimes(1); expect(getAccessToken()).toBeNull();
  });
  it("does not expose an unverified session when canonical me fails", async () => {
    const fetch = vi.fn().mockResolvedValueOnce(new Response('{"access_token":"signed"}'))
      .mockResolvedValueOnce(new Response("{}", { status: 403 })); vi.stubGlobal("fetch", fetch);
    await expect(loginPassword("user", "private")).rejects.toThrow("登录失败");
    expect(getAccessToken()).toBeNull();
  });
});

describe("server login policy gate", () => {
  async function renderPolicy(body: unknown, status = 200) {
    vi.stubGlobal("IS_REACT_ACT_ENVIRONMENT", true);
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue(new Response(JSON.stringify(body), { status })));
    const container = document.createElement("div");
    const root = createRoot(container);
    await act(async () => { root.render(createElement(LocalLoginGate, { children: "business catalog" })); });
    const text = container.textContent;
    await act(async () => root.unmount());
    return text;
  }
  it("preserves the explicitly enabled legacy development UI", async () => {
    expect(await renderPolicy({ allowDevToken: true })).toContain("business catalog");
  });
  it("requires human login before mounting business consumers", async () => {
    const text = await renderPolicy({ allowDevToken: false, tokenUrlConfigured: true, grantTypes: ["password"] });
    expect(text).toContain("登录名"); expect(text).not.toContain("business catalog");
  });
  it("fails closed for unreadable or unsupported login configuration", async () => {
    for (const [body, status] of [[{}, 200], [{ allowDevToken: false }, 200], [{}, 503]] as const) {
      const text = await renderPolicy(body, status);
      expect(text).toContain("登录服务暂不可用"); expect(text).not.toContain("business catalog");
    }
  });
});
